
const files = {"/index.html":"<!doctype html>\n<html lang=\"ru\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"description\" content=\"Кубок мира по регби 2027 в Австралии: обратный отсчёт, группы, расписание и трансляции.\">\n  <title>Кубок мира по регби 2027 — Австралия</title>\n  <link rel=\"icon\" href=\"/favicon.svg\">\n  <link rel=\"stylesheet\" href=\"/assets/css/site.css\">\n</head>\n<body>\n  <div id=\"menu-container\"></div>\n  <main>\n    <section class=\"hero\">\n      <div class=\"hero-glow\"></div>\n      <div class=\"shell hero-grid\">\n        <div class=\"hero-copy\">\n          <div class=\"eyebrow\"><span></span> Австралия · 1 октября — 13 ноября 2027</div>\n          <h1>Главный турнир<br><em>мирового регби</em></h1>\n          <p class=\"lead\">24 сборные, 52 матча и шесть недель большого регби. Всё самое важное о Кубке мира 2027 — на одной понятной странице.</p>\n          <div class=\"hero-actions\">\n            <a class=\"button primary\" href=\"/schedule\">Смотреть расписание</a>\n            <a class=\"button ghost\" href=\"/streams\">Перейти к трансляциям</a>\n          </div>\n        </div>\n        <div class=\"countdown-panel\" aria-label=\"Обратный отсчёт до начала турнира\">\n          <div class=\"ball-mark\" aria-hidden=\"true\"><span>RWC</span><b>27</b></div>\n          <div class=\"countdown-label\">До стартового свистка</div>\n          <div class=\"countdown\" id=\"countdown\">\n            <div><strong id=\"days\">—</strong><span>дней</span></div>\n            <div><strong id=\"hours\">—</strong><span>часов</span></div>\n            <div><strong id=\"minutes\">—</strong><span>минут</span></div>\n            <div><strong id=\"seconds\">—</strong><span>секунд</span></div>\n          </div>\n          <div class=\"opening-match\"><span>Матч открытия</span><b>Австралия — Гонконг</b><small>Перт · 1 октября 2027</small></div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"quick-strip\">\n      <div class=\"shell quick-grid\">\n        <div><strong>24</strong><span>сборные</span></div>\n        <div><strong>52</strong><span>матча</span></div>\n        <div><strong>7</strong><span>городов</span></div>\n        <div><strong>8</strong><span>стадионов</span></div>\n      </div>\n    </section>\n\n    <section class=\"section shell\">\n      <div class=\"section-head\">\n        <div><span class=\"kicker\">Групповой этап</span><h2>Шесть групп. Одна цель.</h2></div>\n        <p>Впервые в истории на Кубке мира сыграют 24 команды. В плей-офф выйдут по две лучшие сборные каждой группы и четыре лучшие команды с третьих мест.</p>\n      </div>\n      <div class=\"pools\">\n        <article class=\"pool\"><span>A</span><h3>Группа A</h3><ol><li>Новая Зеландия</li><li>Австралия</li><li>Чили</li><li>Гонконг</li></ol></article>\n        <article class=\"pool\"><span>B</span><h3>Группа B</h3><ol><li>ЮАР</li><li>Италия</li><li>Грузия</li><li>Румыния</li></ol></article>\n        <article class=\"pool\"><span>C</span><h3>Группа C</h3><ol><li>Аргентина</li><li>Фиджи</li><li>Испания</li><li>Канада</li></ol></article>\n        <article class=\"pool\"><span>D</span><h3>Группа D</h3><ol><li>Ирландия</li><li>Шотландия</li><li>Уругвай</li><li>Португалия</li></ol></article>\n        <article class=\"pool\"><span>E</span><h3>Группа E</h3><ol><li>Франция</li><li>Япония</li><li>США</li><li>Самоа</li></ol></article>\n        <article class=\"pool\"><span>F</span><h3>Группа F</h3><ol><li>Англия</li><li>Уэльс</li><li>Тонга</li><li>Зимбабве</li></ol></article>\n      </div>\n    </section>\n\n    <section class=\"section shell feature-band\">\n      <div><span class=\"kicker\">Турнир в цифрах</span><h2>Самый большой Кубок мира в истории</h2><p>Новый раунд 1/8 финала, 19 игровых дней и семь городов от Перта до Сиднея.</p></div>\n      <a class=\"button primary\" href=\"/about\">Как устроен турнир</a>\n    </section>\n  </main>\n  <footer><div class=\"shell\"><b>RUGBY 2027</b><span>Независимый русскоязычный проект о Кубке мира</span></div></footer>\n  <script src=\"/menu.js\"></script>\n  <script>\n    const target = new Date(\"2027-10-01T19:45:00+08:00\").getTime();\n    function tick() {\n      const left = Math.max(0, target - Date.now());\n      const values = [Math.floor(left / 86400000), Math.floor(left / 3600000) % 24, Math.floor(left / 60000) % 60, Math.floor(left / 1000) % 60];\n      [\"days\",\"hours\",\"minutes\",\"seconds\"].forEach((id,i) => document.getElementById(id).textContent = String(values[i]).padStart(i ? 2 : 1,\"0\"));\n    }\n    tick(); setInterval(tick,1000);\n  </script>\n</body>\n</html>\n","/about.html":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>О турнире — Rugby 2027</title><link rel=\"icon\" href=\"/favicon.svg\"><link rel=\"stylesheet\" href=\"/assets/css/site.css\"></head><body>\n<div id=\"menu-container\"></div><main><section class=\"page-hero\"><div class=\"shell\"><span class=\"kicker\">Австралия 2027</span><h1>О турнире</h1><p>Крупнейший Кубок мира в истории: новый формат, больше команд и дополнительный раунд плей-офф.</p></div></section>\n<section class=\"section shell\"><div class=\"content-grid\">\n<article class=\"info-card\"><span class=\"kicker\">Формат</span><h3>24 сборные</h3><p>Шесть групп по четыре команды. В 1/8 финала выходят 16 участников.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">География</span><h3>7 городов</h3><p>Аделаида, Брисбен, Мельбурн, Ньюкасл, Перт, Сидней и Таунсвилл.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">Масштаб</span><h3>52 матча</h3><p>Турнир пройдёт на восьми стадионах в течение шести недель.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">Старт</span><h3>Перт</h3><p>Австралия откроет турнир матчем против дебютанта — сборной Гонконга.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">Финал</span><h3>Сидней</h3><p>Новый чемпион мира определится 13 ноября на Stadium Australia.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">Особенность</span><h3>1/8 финала</h3><p>Новый раунд плей-офф впервые появится в мужском Кубке мира.</p></article>\n</div></section></main><footer><div class=\"shell\"><b>RUGBY 2027</b><span>Коротко и понятно о главном турнире</span></div></footer><script src=\"/menu.js\"></script></body></html>\n","/schedule.html":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Расписание — Rugby 2027</title><link rel=\"icon\" href=\"/favicon.svg\"><link rel=\"stylesheet\" href=\"/assets/css/site.css\"></head><body>\n<div id=\"menu-container\"></div><main>\n<section class=\"page-hero\"><div class=\"shell\"><span class=\"kicker\">52 матча · 19 игровых дней</span><h1>Расписание</h1><p>Ключевые даты Кубка мира 2027. Полный календарь будет добавлен в удобном виде с переводом времени на московское.</p></div></section>\n<section class=\"section shell\"><div class=\"schedule-list\">\n<article class=\"match-row\"><time>1 октября 2027</time><div><b>Австралия — Гонконг</b><br><span>Матч открытия · Перт</span></div><span>Группа A</span></article>\n<article class=\"match-row\"><time>17 октября 2027</time><div><b>Супервоскресенье</b><br><span>Пять матчей в заключительный день группового этапа</span></div><span>Группы</span></article>\n<article class=\"match-row\"><time>23–24 октября</time><div><b>1/8 финала</b><br><span>Впервые в истории Кубка мира</span></div><span>Плей-офф</span></article>\n<article class=\"match-row\"><time>30–31 октября</time><div><b>Четвертьфиналы</b><br><span>Брисбен и Сидней</span></div><span>Плей-офф</span></article>\n<article class=\"match-row\"><time>5–6 ноября</time><div><b>Полуфиналы</b><br><span>Сидней</span></div><span>Плей-офф</span></article>\n<article class=\"match-row\"><time>13 ноября 2027</time><div><b>Финал Кубка мира</b><br><span>Stadium Australia · Сидней</span></div><span>Финал</span></article>\n</div><p class=\"notice\" style=\"margin-top:20px\">Официальный календарь всех 52 матчей опубликован организаторами. Мы подготовим русскоязычную версию без перегруженных таблиц.</p></section>\n</main><footer><div class=\"shell\"><b>RUGBY 2027</b><span>Все даты сверены с официальным календарём турнира</span></div></footer><script src=\"/menu.js\"></script></body></html>\n","/history.html":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>История — Rugby 2027</title><link rel=\"icon\" href=\"/favicon.svg\"><link rel=\"stylesheet\" href=\"/assets/css/site.css\"></head><body>\n<div id=\"menu-container\"></div><main><section class=\"page-hero\"><div class=\"shell\"><span class=\"kicker\">1987 — 2027</span><h1>История Кубка мира</h1><p>Десять завершённых турниров, четыре чемпиона и новая глава, которая начнётся в Австралии.</p></div></section>\n<section class=\"section shell\"><div class=\"content-grid\">\n<article class=\"info-card\"><span class=\"kicker\">1987</span><h3>Новая Зеландия</h3><p>Первый Кубок мира. Хозяева победили Францию в финале.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">1991 · 1999</span><h3>Австралия</h3><p>Два титула «Уоллабис» и единственная команда, выигравшая оба финала 1990-х.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">1995</span><h3>ЮАР</h3><p>Домашняя победа, ставшая одним из главных символов объединения страны.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">2003</span><h3>Англия</h3><p>Первый и пока единственный чемпион мира из Северного полушария.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">2011 · 2015</span><h3>Новая Зеландия</h3><p>Первая сборная, защитившая титул и выигравшая турнир трижды.</p></article>\n<article class=\"info-card\"><span class=\"kicker\">2007 · 2019 · 2023</span><h3>ЮАР</h3><p>Четыре титула сделали «Спрингбокс» самой успешной сборной турнира.</p></article>\n</div><div class=\"feature-band\"><div><span class=\"kicker\">Следующая глава</span><h2>Австралия 2027</h2><p>В год 40-летия Кубок мира впервые примет 24 сборные.</p></div><a class=\"button primary\" href=\"/\">К группам 2027</a></div></section></main>\n<footer><div class=\"shell\"><b>RUGBY 2027</b><span>История продолжается</span></div></footer><script src=\"/menu.js\"></script></body></html>\n","/streams.html":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Трансляции — Rugby 2027</title><link rel=\"icon\" href=\"/favicon.svg\"><link rel=\"stylesheet\" href=\"/assets/css/site.css\"></head><body>\n<div id=\"menu-container\"></div><main>\n<section class=\"page-hero\"><div class=\"shell\"><span class=\"kicker\">Смотреть регби</span><h1>Трансляции</h1><p>Простой раздел без лишних переходов: текущий эфир, статус и ближайшие матчи — всё сразу перед глазами.</p></div></section>\n<section class=\"section shell\"><div class=\"stream-layout\">\n<article class=\"video-card\"><div class=\"video-stage\"><div><div class=\"play\">▶</div><h2 style=\"font-size:34px\">Эфир появится здесь</h2><p>Перед началом матча на этой странице появится активный видеоплеер.</p></div></div><div class=\"stream-meta\"><span class=\"status\">Сейчас эфира нет</span><h3>Следующая трансляция будет объявлена позже</h3><p class=\"lead\" style=\"font-size:14px\">Если эфир уже должен идти, обновите страницу один раз. Дополнительных действий не потребуется.</p></div></article>\n<aside class=\"side-card\"><span class=\"kicker\">Как смотреть</span><h2 style=\"font-size:32px\">Три простых шага</h2><ol class=\"steps\"><li><b>01</b><span>Откройте этот раздел перед матчем.</span></li><li><b>02</b><span>Нажмите кнопку запуска в центре плеера.</span></li><li><b>03</b><span>Разверните видео на весь экран.</span></li></ol><div class=\"notice\">Время матчей на сайте указывается по Москве.</div></aside>\n</div></section></main><footer><div class=\"shell\"><b>RUGBY 2027</b><span>Независимый русскоязычный проект</span></div></footer><script src=\"/menu.js\"></script></body></html>\n","/partners.html":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Партнёры — Rugby 2027</title><link rel=\"icon\" href=\"/favicon.svg\"><link rel=\"stylesheet\" href=\"/assets/css/site.css\"></head><body>\n<div id=\"menu-container\"></div><main><section class=\"page-hero\"><div class=\"shell\"><span class=\"kicker\">Вместе с нами</span><h1>Партнёры</h1><p>Здесь появятся проверенные партнёры нашего русскоязычного проекта о Кубке мира 2027.</p></div></section>\n<section class=\"section shell\"><div class=\"feature-band\" style=\"margin:0\"><div><span class=\"kicker\">Раздел готовится</span><h2>Партнёрские материалы — позже</h2><p>Мы ничего не публикуем до официального согласования. Контактные данные также пока скрыты.</p></div></div></section></main><footer><div class=\"shell\"><b>RUGBY 2027</b><span>Независимый русскоязычный проект</span></div></footer><script src=\"/menu.js\"></script></body></html>\n","/robots.txt":"User-agent: *\nAllow: /\n\nSitemap: https://rugby2027.ru/sitemap.xml\n","/sitemap.xml":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url><loc>https://rugby2027.ru/</loc><changefreq>weekly</changefreq><priority>1.0</priority></url>\n  <url><loc>https://rugby2027.ru/schedule</loc><changefreq>weekly</changefreq><priority>0.9</priority></url>\n  <url><loc>https://rugby2027.ru/streams</loc><changefreq>daily</changefreq><priority>0.9</priority></url>\n  <url><loc>https://rugby2027.ru/about</loc><changefreq>monthly</changefreq><priority>0.7</priority></url>\n  <url><loc>https://rugby2027.ru/history</loc><changefreq>monthly</changefreq><priority>0.7</priority></url>\n  <url><loc>https://rugby2027.ru/partners</loc><changefreq>monthly</changefreq><priority>0.6</priority></url>\n</urlset>\n","/favicon.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\">\n  <path d=\"M50 10\n           C30 10, 20 30, 20 50\n           C20 75, 40 90, 50 95\n           C60 90, 80 75, 80 50\n           C80 30, 70 10, 50 10 Z\"\n        fill=\"none\"\n        stroke=\"white\"\n        stroke-width=\"8\"\n        stroke-linecap=\"round\"/>\n  <path d=\"M35 80\n           Q50 85, 65 80\"\n        fill=\"none\"\n        stroke=\"white\"\n        stroke-width=\"6\"\n        stroke-linecap=\"round\"/>\n</svg>\n","/menu.html":"<header class=\"site-header\">\n  <div class=\"shell nav\">\n    <a class=\"brand\" href=\"/\" aria-label=\"Rugby 2027 — главная\"><span class=\"brand-mark\">27</span><span>RUGBY 2027</span></a>\n    <nav class=\"desktop-nav\" aria-label=\"Основное меню\">\n      <a href=\"/\">Главная</a><a href=\"/schedule\">Расписание</a><a href=\"/about\">О турнире</a><a href=\"/history\">История</a><a href=\"/partners\">Партнёры</a><a class=\"nav-live\" href=\"/streams\">Трансляции</a>\n    </nav>\n    <button class=\"menu-toggle\" id=\"menuToggle\" type=\"button\" aria-label=\"Открыть меню\" aria-expanded=\"false\">☰</button>\n    <nav class=\"mobile-nav\" id=\"mobileNav\" aria-label=\"Мобильное меню\">\n      <a href=\"/\">Главная</a><a href=\"/schedule\">Расписание</a><a href=\"/about\">О турнире</a><a href=\"/history\">История</a><a href=\"/partners\">Партнёры</a><a href=\"/streams\">Трансляции</a>\n    </nav>\n  </div>\n</header>\n","/menu.js":"(async function () {\n  const host = document.getElementById(\"menu-container\");\n  if (!host) return;\n  try {\n    const response = await fetch(\"/menu.html\");\n    host.innerHTML = await response.text();\n    const toggle = document.getElementById(\"menuToggle\");\n    const nav = document.getElementById(\"mobileNav\");\n    toggle?.addEventListener(\"click\", () => {\n      const open = nav.classList.toggle(\"open\");\n      toggle.setAttribute(\"aria-expanded\", String(open));\n      toggle.textContent = open ? \"×\" : \"☰\";\n    });\n    const current = location.pathname.replace(/\\.html$/, \"\") || \"/\";\n    host.querySelectorAll(\"a\").forEach(link => {\n      const target = new URL(link.href).pathname.replace(/\\.html$/, \"\") || \"/\";\n      if (target === current) link.setAttribute(\"aria-current\", \"page\");\n    });\n  } catch {}\n})();\n","/assets/css/site.css":"@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Oswald:wght@500;600&display=swap');\n:root{--ink:#f5f1e8;--muted:#a9ada8;--bg:#07100d;--panel:#101b16;--panel2:#14231c;--lime:#c9f64b;--gold:#e5b969;--line:rgba(255,255,255,.11);--shell:1180px}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Manrope,system-ui,sans-serif;line-height:1.5}a{color:inherit;text-decoration:none}button{font:inherit}.shell{width:min(var(--shell),calc(100% - 40px));margin:auto}\n.site-header{position:sticky;top:0;z-index:20;background:rgba(7,16,13,.86);border-bottom:1px solid var(--line);backdrop-filter:blur(18px)}.nav{height:76px;display:flex;align-items:center;justify-content:space-between;gap:28px}.brand{display:flex;align-items:center;gap:11px;font:600 20px Oswald,sans-serif;letter-spacing:.08em}.brand-mark{width:34px;height:44px;border:2px solid var(--lime);border-radius:55% 45% 55% 45%/65% 65% 35% 35%;display:grid;place-items:center;color:var(--lime);font-size:11px;transform:rotate(-12deg)}.desktop-nav{display:flex;align-items:center;gap:26px;font-size:14px;font-weight:600;color:#d4d8d4}.desktop-nav a:hover,.desktop-nav a[aria-current=page]{color:var(--lime)}.nav-live{padding:10px 16px;border:1px solid rgba(201,246,75,.36);border-radius:999px;color:var(--lime)!important}.menu-toggle{display:none;background:none;border:0;color:var(--ink);font-size:28px}.mobile-nav{display:none}\n.hero{position:relative;overflow:hidden;padding:92px 0 74px;background:radial-gradient(circle at 74% 40%,rgba(40,104,70,.5),transparent 33%),linear-gradient(135deg,#07100d 15%,#0d2117 100%)}.hero:before{content:\"\";position:absolute;inset:0;opacity:.14;background-image:repeating-linear-gradient(125deg,transparent 0 35px,rgba(255,255,255,.1) 36px 37px)}.hero-glow{position:absolute;width:480px;height:480px;right:-80px;top:-140px;border-radius:50%;border:90px solid rgba(201,246,75,.035)}.hero-grid{position:relative;display:grid;grid-template-columns:1.15fr .85fr;gap:80px;align-items:center}.eyebrow,.kicker{color:var(--lime);font-size:12px;font-weight:800;letter-spacing:.18em;text-transform:uppercase}.eyebrow{display:flex;align-items:center;gap:10px}.eyebrow span{width:28px;height:2px;background:var(--lime)}h1,h2{font-family:Oswald,sans-serif;text-transform:uppercase;line-height:.98;margin:20px 0}h1{font-size:clamp(58px,7.2vw,104px);letter-spacing:-.035em}h1 em{color:var(--lime);font-style:normal}h2{font-size:clamp(38px,5vw,62px);letter-spacing:-.02em}.lead{max-width:660px;color:#c4c9c5;font-size:18px;line-height:1.75}.hero-actions{display:flex;gap:14px;margin-top:34px;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;min-height:50px;padding:0 23px;border-radius:8px;font-weight:800;font-size:14px}.primary{background:var(--lime);color:#07100d}.primary:hover{background:#dbff77}.ghost{border:1px solid var(--line);background:rgba(255,255,255,.04)}.ghost:hover{border-color:var(--lime);color:var(--lime)}\n.countdown-panel{position:relative;padding:32px;border:1px solid rgba(201,246,75,.22);background:linear-gradient(145deg,rgba(26,54,39,.83),rgba(10,23,17,.95));border-radius:24px;box-shadow:0 28px 70px rgba(0,0,0,.35)}.ball-mark{position:absolute;right:28px;top:-42px;width:92px;height:120px;border:2px solid var(--gold);border-radius:52% 48% 53% 47%/63% 64% 36% 37%;transform:rotate(13deg);display:grid;place-content:center;text-align:center;color:var(--gold)}.ball-mark span{font:600 13px Oswald}.ball-mark b{font:600 34px Oswald}.countdown-label{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin-bottom:22px}.countdown{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.countdown div{padding:16px 6px;background:rgba(0,0,0,.22);border-radius:10px;text-align:center}.countdown strong{display:block;font:600 clamp(28px,3vw,42px) Oswald}.countdown span{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.opening-match{display:grid;gap:4px;margin-top:22px;padding-top:20px;border-top:1px solid var(--line)}.opening-match span,.opening-match small{color:var(--muted);font-size:12px}.opening-match b{font-size:18px}\n.quick-strip{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:#0a1511}.quick-grid{display:grid;grid-template-columns:repeat(4,1fr)}.quick-grid div{display:flex;align-items:baseline;justify-content:center;gap:10px;padding:28px;border-right:1px solid var(--line)}.quick-grid div:last-child{border:0}.quick-grid strong{font:600 32px Oswald;color:var(--lime)}.quick-grid span{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}\n.section{padding-top:96px;padding-bottom:96px}.section-head{display:grid;grid-template-columns:1.2fr .8fr;gap:80px;align-items:end;margin-bottom:40px}.section-head p{color:var(--muted);line-height:1.75}.pools{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.pool{position:relative;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:26px;overflow:hidden;transition:.25s}.pool:hover{transform:translateY(-4px);border-color:rgba(201,246,75,.45);background:var(--panel2)}.pool>span{position:absolute;right:16px;top:4px;font:600 76px Oswald;color:rgba(201,246,75,.07)}.pool h3{margin:0 0 18px;font:600 15px Oswald;text-transform:uppercase;letter-spacing:.12em;color:var(--lime)}.pool ol{list-style:none;padding:0;margin:0;counter-reset:team}.pool li{counter-increment:team;padding:10px 0;border-top:1px solid rgba(255,255,255,.07);font-weight:600}.pool li:before{content:\"0\" counter(team);font-size:10px;color:var(--muted);margin-right:12px}.feature-band{margin-bottom:96px;padding:46px 52px;background:linear-gradient(100deg,#173525,#0d1c16);border:1px solid rgba(201,246,75,.2);border-radius:22px;display:flex;justify-content:space-between;align-items:center;gap:40px}.feature-band h2{font-size:42px;margin:12px 0}.feature-band p{color:var(--muted);margin:0}\n.page-hero{padding:72px 0 54px;background:linear-gradient(135deg,#0d2117,#07100d);border-bottom:1px solid var(--line)}.page-hero h1{font-size:clamp(52px,7vw,84px);margin-bottom:15px}.page-hero p{max-width:720px;color:var(--muted);font-size:17px}.content-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.info-card{padding:28px;background:var(--panel);border:1px solid var(--line);border-radius:16px}.info-card h3{font:600 22px Oswald;text-transform:uppercase;margin:8px 0 12px}.info-card p{color:var(--muted)}.stream-layout{display:grid;grid-template-columns:1.4fr .6fr;gap:20px}.video-card{background:#020403;border:1px solid var(--line);border-radius:18px;overflow:hidden}.video-stage{aspect-ratio:16/9;display:grid;place-content:center;text-align:center;padding:30px;background:radial-gradient(circle,#173525,#050a08)}.video-stage .play{width:68px;height:68px;border-radius:50%;background:var(--lime);color:#07100d;display:grid;place-items:center;margin:auto;font-size:26px}.video-stage p{color:var(--muted);max-width:420px}.stream-meta{padding:22px}.status{display:inline-flex;gap:8px;align-items:center;color:var(--gold);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.12em}.status:before{content:\"\";width:8px;height:8px;border-radius:50%;background:var(--gold)}.side-card{padding:24px;background:var(--panel);border:1px solid var(--line);border-radius:18px}.steps{padding:0;list-style:none}.steps li{display:flex;gap:12px;padding:15px 0;border-top:1px solid var(--line);color:var(--muted)}.steps b{color:var(--lime)}.schedule-list{display:grid;gap:12px}.match-row{display:grid;grid-template-columns:150px 1fr auto;align-items:center;gap:24px;padding:20px 24px;background:var(--panel);border:1px solid var(--line);border-radius:14px}.match-row time{font-weight:800;color:var(--lime)}.match-row b{font-size:17px}.match-row span{color:var(--muted);font-size:13px}.notice{padding:22px;border:1px solid rgba(229,185,105,.3);background:rgba(229,185,105,.07);border-radius:14px;color:#ddd1ba}\nfooter{border-top:1px solid var(--line);padding:30px 0;color:var(--muted);font-size:12px}footer .shell{display:flex;justify-content:space-between;gap:20px}footer b{color:var(--ink);letter-spacing:.12em}\n@media(max-width:900px){.desktop-nav{display:none}.menu-toggle{display:block}.mobile-nav.open{display:grid;position:absolute;top:76px;left:0;right:0;padding:20px;background:#0b1712;border-bottom:1px solid var(--line);gap:8px}.mobile-nav a{padding:12px}.hero{padding-top:62px}.hero-grid,.section-head,.stream-layout{grid-template-columns:1fr;gap:42px}.pools,.content-grid{grid-template-columns:repeat(2,1fr)}.ball-mark{right:24px}.feature-band{align-items:flex-start;flex-direction:column}.match-row{grid-template-columns:110px 1fr}}\n@media(max-width:620px){.shell{width:min(100% - 28px,var(--shell))}.nav{height:66px}.mobile-nav.open{top:66px}h1{font-size:54px}.hero{padding:46px 0}.lead{font-size:16px}.hero-actions .button{width:100%}.countdown-panel{padding:22px;margin-top:20px}.ball-mark{width:66px;height:88px;top:-34px}.ball-mark b{font-size:25px}.countdown{gap:5px}.countdown div{padding:13px 2px}.quick-grid{grid-template-columns:repeat(2,1fr)}.quick-grid div:nth-child(2){border-right:0}.quick-grid div:nth-child(-n+2){border-bottom:1px solid var(--line)}.section{padding-top:68px;padding-bottom:68px}.pools,.content-grid{grid-template-columns:1fr}.feature-band{margin-inline:14px;padding:30px 24px}.match-row{grid-template-columns:1fr;gap:5px}footer .shell{flex-direction:column}}\n","/assets/css/menu.css":"/* ================================\n   MENU BUTTON (BURGER)\n   ================================ */\n\n.menu-btn {\n  position: fixed;\n  top: 18px;\n  right: 18px;\n  width: 36px;\n  height: 26px;\n\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n\n  background: none;\n  border: none;\n  padding: 0;\n  cursor: pointer;\n\n  z-index: 3001;\n}\n\n.menu-btn span {\n  height: 3px;\n  background: #f5f8ff;\n  border-radius: 3px;\n  transition: transform .3s ease, opacity .2s ease;\n}\n\n.menu-btn.active span:nth-child(1) {\n  transform: translateY(11px) rotate(45deg);\n}\n\n.menu-btn.active span:nth-child(2) {\n  opacity: 0;\n}\n\n.menu-btn.active span:nth-child(3) {\n  transform: translateY(-11px) rotate(-45deg);\n}\n\n/* ================================\n   MENU OVERLAY (BACKGROUND BLUR)\n   ================================ */\n\n.menu-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(6, 14, 32, 0.55);\n  backdrop-filter: blur(14px) saturate(120%);\n  -webkit-backdrop-filter: blur(14px) saturate(120%);\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity .35s ease;\n  z-index: 1999;\n}\n\n.menu-overlay.active {\n  opacity: 1;\n  pointer-events: auto;\n}\n\n/* ================================\n   SIDE MENU (GLASS PANEL)\n   ================================ */\n\n.side-menu {\n  position: fixed;\n  top: 0;\n  right: 0;\n  width: min(64vw, 300px);\n  height: 100vh;\n\n  background: linear-gradient(\n    180deg,\n    rgba(14, 30, 64, 0.78),\n    rgba(6, 14, 32, 0.88)\n  );\n\n  backdrop-filter: blur(22px) saturate(140%);\n  -webkit-backdrop-filter: blur(22px) saturate(140%);\n\n  box-shadow:\n    -18px 0 46px rgba(0,0,0,0.45),\n    inset 1px 0 0 rgba(255,255,255,0.07);\n\n  transform: translateX(100%);\n  transition: transform .4s cubic-bezier(.22,.61,.36,1);\n\n  z-index: 2000;\n\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n}\n\n.side-menu.active {\n  transform: translateX(0);\n}\n\n/* ================================\n   MENU LINKS\n   ================================ */\n\n.side-menu a {\n  position: relative;\n  color: #e9f0ff;\n  text-decoration: none;\n  font-size: 1.1rem;\n  letter-spacing: 0.12em;\n  padding: 14px 0;\n  width: 100%;\n  text-align: center;\n  opacity: 0.92;\n  transition: opacity .25s ease;\n}\n\n.side-menu a:hover {\n  opacity: 1;\n}\n\n.side-menu a::after {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  bottom: 0;\n  transform: translateX(-50%);\n  width: 42px;\n  height: 1px;\n  background: rgba(255,255,255,0.12);\n}\n\n.side-menu a:last-child::after {\n  display: none;\n}\n\n/* ================================\n   CLOSE BUTTON (X)\n   ================================ */\n\n.menu-close {\n  position: absolute;\n  top: 18px;\n  right: 18px;\n  font-size: 30px;\n  color: rgba(255,255,255,0.9);\n  cursor: pointer;\n}\n\n/* ================================\n   BODY LOCK + PAGE BLUR\n   ================================ */\n\nbody.menu-open {\n  overflow: hidden;\n}\n\nbody.menu-open main,\nbody.menu-open .page {\n  filter: blur(5px) brightness(0.9);\n  transition: filter .35s ease;\n}\n\nmain,\n.page {\n  transition: filter .35s ease;\n}\n\n/* ================================\n   TAP HIGHLIGHT OFF\n   ================================ */\n\n* {\n  -webkit-tap-highlight-color: transparent;\n}\n\nbutton {\n  outline: none;\n}\n"};
const aliases = {
  "/": "/index.html",
  "/about": "/about.html",
  "/schedule": "/schedule.html",
  "/history": "/history.html",
  "/streams": "/streams.html",
  "/partners": "/partners.html"
};
const types = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".svg": "image/svg+xml; charset=utf-8",
  ".xml": "application/xml; charset=utf-8",
  ".txt": "text/plain; charset=utf-8"
};
export default {
  async fetch(request) {
    const url = new URL(request.url);
    const requested = decodeURIComponent(url.pathname);
    const path = aliases[requested] || requested;
    const body = files[path];
    if (body === undefined) {
      return new Response("Страница не найдена", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
    }
    const extension = path.slice(path.lastIndexOf("."));
    return new Response(request.method === "HEAD" ? null : body, {
      status: 200,
      headers: {
        "content-type": types[extension] || "application/octet-stream",
        "cache-control": path.endsWith(".html") ? "no-cache" : "public, max-age=3600",
        "x-content-type-options": "nosniff"
      }
    });
  }
};
